public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;
    for (int i = 0; i < strings.size(); i++) {
        for (int j = i + 1; j < strings.size(); j++) {
            int length = longestCommonSubstring(strings.get(i), strings.get(j));
            maxLength = Math.max(maxLength, length);
        }
    }
    return maxLength;
}

private int longestCommonSubstring(String str1, String str2) {
    int[][] dp = new int[str1.length() + 1][str2.length() + 1];
    int maxLength = 0;
    for (int i = 0; i < str1.length(); i++) {
        for (int j = 0; j < str2.length(); j++) {
            if (str1.charAt(i) == str2.charAt(j)) {
                dp[i + 1][j + 1] = dp[i][j] + 1;
                maxLength = Math.max(maxLength, dp[i + 1][j + 1]);
            }
        }
    }
    return maxLength;
}

