public static int countOilDeposits(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] == '@') {
                count++;
                floodFill(grid, i, j, '@');
            }
        }
    }
    return count;
}

private static void floodFill(char[][] grid, int i, int j, char target) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length) {
        return;
    }
    if (grid[i][j] != target) {
        return;
    }
    grid[i][j] = '*';
    floodFill(grid, i + 1, j, target);
    floodFill(grid, i - 1, j, target);
    floodFill(grid, i, j + 1, target);
    floodFill(grid, i, j - 1, target);
}
