public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    int[] visited = new int[n];
    Arrays.fill(visited, Integer.MIN_VALUE);
    visited[start[1]] = start[0];

    while (visited[end[1]] == Integer.MIN_VALUE) {
        for (int i = 0; i < paths.length; i++) {
            int[] current = paths[i];
            int source = current[0];
            int destination = current[1];
            if (visited[source] == Integer.MIN_VALUE) continue;
            if (visited[destination] == Integer.MIN_VALUE || visited[destination] > visited[source] + 1) {
                visited[destination] = visited[source] + 1;
            }
        }
    }

    if (visited[end[1]] == Integer.MIN_VALUE) {
        return "cannot be travelled";
    } else {
        return "can be travelled";
    }
}
