public double trimMean(int[] arr) {
    // Calculate the percentiles and remove the smallest and largest n% of the elements
    int percentile = arr.length / 20;
    int[] trimmedArr = new int[arr.length - 2 * percentile];
    System.arraycopy(arr, percentile, trimmedArr, 0, trimmedArr.length);

    // Calculate the sum of the remaining elements
    int sum = 0;
    for (int i = 0; i < trimmedArr.length; i++) {
        sum += trimmedArr[i];
    }

    // Calculate the mean of the remaining elements
    double mean = sum / (double) trimmedArr.length;

    return mean;
}
