public boolean canArrange(int[] arr, int k) {
    int n = arr.length / 2;
    int[] counts = new int[k];
    for (int i = 0; i < n; i++) {
        int a = arr[i];
        int b = arr[i + n];
        int sum = a + b;
        int remainder = sum % k;
        if (remainder == 0) {
            return true;
        } else {
            counts[remainder]++;
        }
    }
    for (int i = 1; i < k; i++) {
        if (counts[i] > 0 && counts[k - i] > 0) {
            return true;
        }
    }
    return false;
}
