    while (!queue.isEmpty()) {
        int node = queue.poll();
        visited[node] = true;
        for (int neighbor : edges[node]) {
            if (!visited[neighbor]) {
                queue.add(neighbor);
                dist[neighbor] = Math.min(dist[neighbor], dist[node] + (hasApple[neighbor] ? 2 : 1));
            }
        }
    }
    return dist[0];
}
