public static int squarePermutations(int[] A) {
    int n = A.length;
    int[][] memo = new int[n][n];
    for (int[] row : memo) Arrays.fill(row, -1);
    return countSquarePermutations(A, 0, memo);
}

private static int countSquarePermutations(int[] A, int i, int[][] memo) {
    if (i == A.length) return 1;
    if (memo[i][i] != -1) return memo[i][i];
    int sum = countSquarePermutations(A, i + 1, memo) * 4;
    for (int j = i + 1; j < A.length; j++) {
        int sqrt = (int) Math.round(Math.sqrt(A[i] + A[j]));
        if (A[i] + A[j] != sqrt * sqrt) continue;
        sum += countSquarePermutations(swap(A, i, j), i + 1, memo);
    }
    memo[i][i] = sum;
    return sum;
}

private static int[] swap(int[] A, int i, int j) {
    int temp = A[i];
    A[i] = A[j];
    A[j] = temp;
    return A;
