public static String doArithmetic(String expression) {
    // Use a regular expression to match numbers, variables, and parentheses
    Pattern pattern = Pattern.compile("([0-9]+|[a-zA-Z]+|\\(|\\))");
    Matcher matcher = pattern.matcher(expression);

    // Create a stack to handle parentheses and operator precedence
    Stack<String> stack = new Stack<>();

    // Evaluate the expression token by token
    while (matcher.find()) {
        String token = matcher.group();
        if (token.equals("(")) {
            // If we encounter an open parenthesis, push it onto the stack
            stack.push(token);
        } else if (token.equals(")")) {
            // If we encounter a close parenthesis, we need to evaluate the expression in the parentheses
            // and then push the result onto the stack
            int start = stack.indexOf("(") + 1;
            int end = stack.size() - 1;
            String subExpression = expression.substring(start, end);
            stack.set(start - 1, String.valueOf(doArithmetic(subExpression)));
        } else if (token.matches("[0-9]+")) {
            // If we encounter a number, push it onto the stack
            stack.push(token);
        } else {
            // If we encounter a variable, perform the arithmetic operation and push the result onto the stack
            double result = 0;
            String operator = stack.pop();
            double num1 = Double.parseDouble(stack.pop());
            double num2 = Double.parseDouble(token);
            switch (operator) {
                case "+":
                    result = num1 + num2;
                    break;
                case "-":
                    result = num1 - num2;
                    break;
                case "*":
                    result = num1 * num2;
                    break;
                case "/":
                    result = num1 / num2;
                    break;
                default:
                    throw new IllegalArgumentException("Unknown operator: " + operator);
            }
            stack.push(String.valueOf(result));
        }
    }

    // If the stack is empty, the expression is invalid and we return an empty string
    if (stack.isEmpty()) {
        return "";
    }

    // If the stack has only one element, we have the result of the entire expression
    String result = stack.pop();
    if (result.equals("")) {
        return "";
    }

    // Convert the result to a double and return it as a string
    try {
        double resultDouble = Double.parseDouble(result);
        return String.valueOf(resultDouble);
    } catch (NumberFormatException e) {
        return "";
    }
}
