package com.example;

public class PerfectSquareSum {
    public static int minPerfectSquareSum(int n) {
        int count = 0;
        while (n > 0) {
            int next = (int) Math.sqrt(n);
            if (next * next == n) {
                count++;
            }
            n -= next;
        }
        return count;
    }
}
